Конечно! Вот пример скрипта на JavaScript, который позволяет пользователям взаимодействовать с веб-сайтом, предоставляя им возможность добавлять, редактировать и удалять записи на странице поддержания (или странице управления, как вы сказали). Этот скрипт предполагает, что на странице уже есть структура HTML для отображения и управления записями.

```javascript
// Получаем ссылки на элементы DOM
const addRecordButton = document.getElementById('addRecordButton');
const recordList = document.getElementById('recordList');
const inputField = document.getElementById('inputField');

// Массив для хранения записей
let records = [];

// Функция для отображения списка записей
function displayRecords() {
    recordList.innerHTML = '';
    records.forEach((record, index) => {
        const listItem = document.createElement('li');
        listItem.textContent = `${index + 1}. ${record.name} - ${record.value}`;
        recordList.appendChild(listItem);
    });
}

// Функция для добавления записи
function addRecord() {
    const value = inputField.value.trim();
    if (value !== '') {
        const newRecord = { id: records.length + 1, name: inputField.value, value: inputField.value };
        records.push(newRecord);
        inputField.value = '';
        displayRecords();
    }
}

// Функция для редактирования записи
function editRecord(event) {
    const index = parseInt(event.target.dataset.index);
    const newValue = event.target.value;
    records[index].value = newValue;
    displayRecords();
}

// Функция для удаления записи
function deleteRecord(event) {
    const index = parseInt(event.target.dataset.index);
    records.splice(index, 1);
    displayRecords();
}

// Обработчики событий
addRecordButton.addEventListener('click', addRecord);

// Предположим, что на странице есть элементы для редактирования и удаления
recordList.addEventListener('click', (event) => {
    if (event.target.tagName === 'LI') {
        event.target.addEventListener('click', editRecord, { capture: true });
        event.stopPropagation();
    }
});

// Отображение первоначальных записей
displayRecords();

